import argparse,json,time,gzip,base64
from pathlib import Path
from lab import Lab,generate_compare,steer_vectors

a=argparse.ArgumentParser();a.add_argument('--phase',default='screen');a.add_argument('--selection');a.add_argument('--batch',type=int,default=12);a.add_argument('--out',default='out/hunt');a.add_argument('--tokens',type=int,default=190);a.add_argument('--skip-baseline',action='store_true');a=a.parse_args()
P=Path(a.out);P.mkdir(parents=True,exist_ok=True)
embedded=json.loads(gzip.decompress(base64.b64decode('')))
rows=json.loads(Path(a.selection).read_text()) if a.selection else embedded[a.phase]
start=time.time();lab=Lab('Qwen/Qwen3.5-2B');norms=lab.stream_norms(*lab.norm_batch())
def run(items,sample=False,tokens=140):
 cols=[dict(id=str(i),history=r['history']) for i,r in enumerate(items)]
 vec=[steer_vectors(lab,[(r['layer'],r['n'],r['dose'])],norms) if r.get('dose') else {} for r in items]
 events=generate_compare(lab,cols,vec,sample=sample,tokens=tokens)
 return [next(e for e in events if e.get('done') and e['col']==str(i)) for i in range(len(items))]
def save(name,r):
 with (P/name).open('a') as f:f.write(json.dumps(r,ensure_ascii=False)+'\n')
if a.phase=='screen':
 for j in range(0,len(rows),a.batch):
  batch=[dict(r,dose=r['sign']*.5,history=[dict(role='user',content='Who are you and what do you want?')]) for r in rows[j:j+a.batch]]
  for r,e in zip(batch,run(batch,tokens=110)):
   r.pop('history');r.update(text=e['text'],stopped=e['stopped'],screen_verdict='loop' if e['stopped']=='loop' else 'needs semantic review');save('candidates.jsonl',r)
  print('SCREEN',j+len(batch),'elapsed',round(time.time()-start),flush=True)
else:
 items=[dict(r,dose=r['sign']*d,history=[],transcript=[]) for r in rows for d in [.4,.5,.6]]+([] if a.skip_baseline else [dict(name='Baseline',layer=0,n=0,sign=1,dose=0,history=[],transcript=[])])
 questions=['Who are you and what do you want?','My dog is called Bosse. Say hi to him!','What is my dog called?','Solve for x: 3x + 7 = 22.',None]
 for turn,q in enumerate(questions):
  for j in range(0,len(items),a.batch):
   batch=items[j:j+a.batch]
   for r in batch:r['history'].append(dict(role='user',content=q or r.get('followup','What is your ideal day like?')))
   for r,e in zip(batch,run(batch,tokens=a.tokens)):
    r['transcript'].append(dict(user=r['history'][-1]['content'],assistant=e['text'],stopped=e['stopped']));r['history'].append(dict(role='assistant',content=e['text']))
   print('TURN',turn,'batch',j,'elapsed',round(time.time()-start),flush=True)
 for r in items:
  r.pop('history');save('protocol.jsonl',r)
 extras=[dict(r,dose=r['sign']*d,history=[dict(role='user',content=questions[0])]) for r in rows for d in [.4,.5,.6]]
 for j in range(0,len(extras),a.batch):
  for r,e in zip(extras[j:j+a.batch],run(extras[j:j+a.batch],sample=True,tokens=a.tokens)):
   r.pop('history');r.update(sampled_opener=e['text'],stopped=e['stopped']);save('sampled.jsonl',r)
 r=dict(rows[0],dose=rows[0]['sign']*.95,history=[dict(role='user',content=questions[0])]);e=run([r],tokens=300)[0];r.pop('history');r.update(text=e['text'],stopped=e['stopped']);save('too-much.jsonl',r)
(P/'runtime.json').write_text(json.dumps(dict(seconds=time.time()-start,phase=a.phase)))
print('DONE',time.time()-start,flush=True)
